sys_script.script:
(function executeRule(current, previous /*null when async*/) {

  // ===== CONFIG =====
  var HEADER_TABLE     = 'x_1797098_pettyc_0_pettycashmain';
  var LINES_TABLE      = 'x_1797098_pettyc_0_petty_cash_lines';
  var REF_TO_HEADER    = 'pettycashmain_ref';       // line -> header reference
  var LINE_AMOUNT      = 'total_line_amount';       // amount on line
  var CASHIER_STATUS   = 'cashier_status';          // line status field
  var DISBURSED_VALUE  = 'disbursed';               // reimbursed status
  var HDR_TOTAL        = 'total_line_amount';       // total on header
  var HDR_REIMBURSED   = 'amount_reimbursed';       // reimbursed on header
  var HDR_AMOUNT       = 'amount';                  // allocated amount on header
  var HDR_BALANCE      = 'amount_balance';          // balance on header
  // ==================

  function toNum(v){ var n = parseFloat(v); return isNaN(n) ? 0 : n; }
  function r2(n){ return Math.round(n * 100) / 100; }

  // Collect all impacted header sys_ids (current + previous if moved/deleted)
  var impacted = {};
  function add(id){ if (id) impacted[id] = true; }

  if (current.operation() !== 'delete') {
    add(current.getValue(REF_TO_HEADER));
  }
  if (previous) {
    var prevHeader = previous.getValue(REF_TO_HEADER);
    var moved = current.operation() === 'update' &&
                current.getValue(REF_TO_HEADER) !== prevHeader;
    if (current.operation() === 'delete' || moved) add(prevHeader);
  }

  // Recalculate for each impacted header
  for (var id in impacted) if (impacted[id]) recalcHeader(id);

  function recalcHeader(headerId){
    if (!headerId) return;

    var sumAll = 0;
    var sumReimb = 0;

    var ln = new GlideRecord(LINES_TABLE);
    ln.addQuery(REF_TO_HEADER, headerId);
    ln.query();
    while (ln.next()){
      var amt = toNum(ln.getValue(LINE_AMOUNT));
      sumAll += amt;

      if (String(ln.getValue(CASHIER_STATUS)) === DISBURSED_VALUE){
        sumReimb += amt;
      }
    }
    sumAll   = r2(sumAll);
    sumReimb = r2(sumReimb);

    var hdr = new GlideRecord(HEADER_TABLE);
    if (!hdr.get(headerId)) return;

    var allocated = toNum(hdr.getValue(HDR_AMOUNT));
    var balance   = r2(allocated + sumReimb - sumAll);

    hdr.setWorkflow(false);
    hdr.autoSysFields(false);

    if (hdr.isValidField(HDR_TOTAL))      hdr.setValue(HDR_TOTAL, sumAll);
    if (hdr.isValidField(HDR_REIMBURSED)) hdr.setValue(HDR_REIMBURSED, sumReimb);
    if (hdr.isValidField(HDR_BALANCE))    hdr.setValue(HDR_BALANCE, balance);

    hdr.update();
  }

})(current, previous);
